-- Alle nieuwe paginateksten in het CMS (14 september 2026).
--
-- De site werkt ook zonder dit script: een sleutel die een rij niet noemt komt
-- uit de seed. Het gaat om de admin. Zonder deze rijen en sleutels ziet een
-- redacteur lege velden, of vindt hij vijf pagina-ingangen helemaal niet terug
-- omdat er geen rij voor bestaat.
--
-- Twee soorten wijzigingen:
--
--   1. Vijf nieuwe rijen voor de gedeelde labels van de detailpagina's en voor
--      de site-brede teksten (voettekst, cookiemelding). Die staan los omdat
--      ze voor álle sectoren, diensten, klantverhalen of vacatures tegelijk
--      gelden, en dus bij geen enkel item horen.
--   2. De nieuwe sleutels bij de zeven bestaande pagina's.
--
-- `jsonb_build_object(...) || data` en `on conflict do nothing`: dit script
-- vult gaten en overschrijft nooit iets wat een redacteur al heeft getypt.


insert into public.cms_paginas (slug, titel, status, volgorde, data, bijgewerkt_op)
values ('sector-detail', 'Sectorpagina''s — gedeelde labels', 'live', 0, '{"herkenningKicker": "Herkenning", "wieKomtKicker": "Wie er komt", "waaromNuKicker": "Waarom nu", "oplossingenKicker": "Pijn → oplossing", "kolomPijnpunt": "Pijnpunt", "kolomKost": "Wat het kost", "kolomOplossing": "Onze oplossing", "kolomLaag": "Laag", "bouwenKicker": "Wat we bouwen", "sluitAanOpLabel": "Sluit aan op:", "aanpakKicker": "Hoe we werken", "dienstenKicker": "Diensten", "faqKicker": "Veelgestelde vragen", "inzichtenKicker": "Inzichten", "inzichtenTitel": "Kennis uit deze sector", "inzichtenAlle": "Alle inzichten", "inzichtenMeer": "Lees meer", "andereKicker": "Andere sectoren", "teamKicker": "Het team", "ctaPersoonLabel": "Wie je spreekt", "ctaKnop": "Plan een gesprek", "ctaKnopTwee": "Bekijk onze aanpak"}'::jsonb, now())
on conflict (slug) do update
   set data = excluded.data || public.cms_paginas.data,
       bijgewerkt_op = now();

