update public.cms_paginas
   set data = '{"heroTitleStart": "Business en IT als ", "heroAccent": "één beweging", "heroTitleEnd": ".", "heroLead": "Sectorkennis, Mendix en AI in één team, van eerste sessie tot werkende software voor de mensen die ermee werken.", "ctaTitel": "Samen bouwen aan schaalbare groei?", "ctaKnop": "Plan een gesprek", "mensenKicker": "De mens centraal", "mensenTitel": "Je werkt met mensen, niet met een leverancier.", "mensenP1": "Geen anonieme delivery-machine: bij ons ken je de mensen die jouw vraagstuk oplossen. Gepassioneerde consultants en engineers die naast je team staan, van eerste sessie tot livegang en daarna. Van wekelijkse Wavetime-sessies tot onze jaarlijkse Company week, we investeren structureel in hoe we sámen werken, niet alleen in wat we opleveren.", "proofKop": "Vertrouwd door", "sectorenMeer": "Niet jouw sector? Plan een verkenning", "casesAlle": "Alle klantverhalen", "mensenAward": "Dat onze mensen hier met plezier werken, blijkt ook extern: The New Wave IT is bekroond in de Computable Werkgevers Awards 2025.", "mensenKnop": "Ontmoet ons team", "mensenLink": "Werken bij The New Wave IT", "inzichtenAlle": "Alle inzichten", "inzichtenMeer": "Lees meer", "dienstenKicker": "Hoe wij het doen", "dienstenTitel": "Jouw uitdaging, drie richtingen naar de oplossing.", "dienstenIntro": "Een proces dat vastloopt, een systeem dat niet meebeweegt, een koers die nog moet landen. Mendix, AI en strategie zijn de drie richtingen waarlangs we dat aanpakken. Elke richting begint met een concreet product van één dag met een vaste prijs, zodat je snel weet waar je aan toe bent.", "sectorenKicker": "Onze sectoren", "sectorenTitel": "Wij spreken de taal van jouw sector.", "sectorenIntro": "Wij kennen de regels, de systemen en de druk waaronder jouw organisatie werkt. Daardoor leveren we sneller iets dat écht past.", "casesKicker": "Klantverhalen", "casesTitel": "Business-impact, geen technische anekdote.", "inzichtenKicker": "Inzichten & thought leadership", "inzichtenTitel": "Sectorkennis die je helpt voorop te lopen", "mensenP2": "Ons doel? Dat jouw mensen er beter van worden. Technologie is het middel, de mens is de maat."}'::jsonb || data,
       bijgewerkt_op = now()
 where slug = 'home';

update public.cms_paginas
   set data = '{"heroTitleStart": "De ondernemende mens zorgt voor ", "heroAccent": "vooruitgang", "heroLead": "Wij geloven dat succesvolle verandering begint bij mensen. Daarom verzorgen wij alle randvoorwaarden voor onze Wavers, en helpen zij onze partners maximaal digitaal versnellen. Zo staat jouw organisatie klaar voor de dag van overmorgen.", "heroKicker": "Over ons", "missieKicker": "Onze missie", "teamKicker": "Het team", "teamKnop": "Kom kennismaken", "missieTitel": "Maximale digitale impact, met de mens als maat.", "missieP1": "We richtten The New Wave IT op vanuit één overtuiging: technologie is het middel, de mens is de maat. Wij zijn geen anonieme delivery-machine. Je werkt met mensen die je vraagstuk écht doorgronden, van de eerste sessie tot livegang en daarna.", "missieP2": "Dat doen we door op elk project de mensen te kiezen van wie de ervaring, skills en ambitie het beste passen bij jouw vraagstuk. Ons doel? Dat elk mens werk doet dat aansluit bij zijn of haar persoonlijke doelen en drijfveren.", "teamTitel": "Ontmoet de Wavers.", "teamP1": "Geen anonieme delivery-machine: je kent de mensen die jouw vraagstuk oplossen. Senior consultants en engineers die de taal van de boardroom én de werkvloer spreken, betrokken als partner.", "teamP2": "Van strategische sessies tot livegang en beheer: hetzelfde team blijft aan boord. Zo houden we vaart, kwaliteit en verantwoordelijkheid bij elkaar. Wekelijkse Wavetime-sessies en een jaarlijkse Company week: structurele investering in hoe we sámen werken.", "ctaTitel": "Benieuwd wat onze mensen voor jouw doelen kunnen betekenen?", "waardenKicker": "Waar wij voor staan", "waardenTitel": "Vier overtuigingen die je terugziet in ons werk", "waarde1Titel": "Mens centraal", "waarde1Tekst": "De mens is de centrale factor in het behalen van business doelstellingen, niet de technologie zelf. Beloning is bij ons gelijk en transparant voor iedereen met dezelfde ervaring, ongeacht gender of achtergrond.", "waarde2Titel": "Pragmatisch", "waarde2Tekst": "We rekenen elke oplossing door op wat jouw vraagstuk daadwerkelijk oplost, en zeggen net zo makkelijk nee tegen een hype die dat niet doet.", "waarde3Titel": "Autoriteit door bewijs", "waarde3Tekst": "Bewezen frameworks (App Factory, OGSM, 3-Horizonsmodel) en concrete resultaten, geen losse claims.", "waarde4Titel": "Duurzaam ondernemen", "waarde4Tekst": "Ondernemen en maatschappelijke bijdrage horen bij elkaar. In 2030 is ons businessmodel 100% CO2-neutraal.", "kpi1Getal": "2023", "kpi1Label": "Opgericht, kantoor in Utrecht", "kpi2Getal": "100%", "kpi2Label": "De mens centraal, op elk project", "kpi3Getal": "2030", "kpi3Label": "Doel: CO2-neutraal businessmodel", "missieFotoAlt": "Wavers in gesprek met een klant", "teamFotoAlt": "Het team achter The New Wave IT", "adresRegel": "Ganzenmarkt 6, 3512 GD Utrecht"}'::jsonb || data,
       bijgewerkt_op = now()
 where slug = 'over-ons';

