update public.cms_paginas
   set data = '{"heroTitleStart": "Mensen die meebouwen, of ", "heroAccent": "een dienst met vaste scope", "heroTitleEnd": ".", "heroLead": "Onze basis is capaciteit: consultants die in jouw team meebouwen aan Mendix en AI. Wil je eerst richting, snelheid of een fundering, dan hebben we daar afgebakende diensten voor, met een vaste scope en een prijs vooraf.", "heroKicker": "Diensten", "kaartInstap": "Instap", "kaartMeer": "Meer over deze dienst →", "basisKicker": "Onze basisdienstverlening · doorlopend", "basisTitel": "Consultant inhuren", "basisTekst": "Waar de meeste van onze samenwerkingen beginnen en eindigen: een consultant die naast je team komt staan en meebouwt. Aan een Mendix-applicatie, aan AI in je processen, of aan allebei, want in de praktijk loopt dat door elkaar heen. Heb je op dat niveau iemand nodig die de richting bewaakt, dan schuift er een strategisch adviseur aan. Je huurt geen uren in, je haalt iemand binnen die je landschap leert kennen en kennis achterlaat.", "basisRol1Label": "Mendix", "basisRol1Naam": "Developer & lead", "basisRol1Tekst": "Bouwt mee in je bestaande teams of zet er een op.", "basisRol2Label": "AI", "basisRol2Naam": "AI-engineer", "basisRol2Tekst": "Van pilot naar productie, binnen jouw kaders.", "basisRol3Label": "Business", "basisRol3Naam": "Analist & product owner", "basisRol3Tekst": "Vertaalt het proces naar wat er gebouwd moet worden.", "basisRol4Label": "Strategie", "basisRol4Naam": "Strategisch adviseur", "basisRol4Tekst": "Bewaakt richting, portfolio en businesscase.", "basisPersoonRol": "Jouw aanspreekpunt", "basisPersoonTekst": "Je maakt vooraf kennis met de persoon zelf, niet met een cv uit een bestand.", "basisInzetLabel": "Inzet", "basisInzetWaarde": "Vanaf één dag per week", "basisPunt1": "Detachering of projectbasis, zonder minimumtermijn van een jaar", "basisPunt2": "Vaste consultants, geen wisselende gezichten", "basisPunt3": "Kennisoverdracht is onderdeel van de opdracht", "basisPunt4": "Tarief stemmen we af op rol, seniority en inzet", "basisCta": "Bespreek je capaciteitsvraag", "basisCtaAlt": "Bekijk wie er bij ons werken →", "instapKicker": "Begin hier", "instapTitel": "Of begin met één dag", "instapIntro": "Wil je liever eerst zien wat het oplevert voordat je mensen inhuurt? Dan starten we met een dag. Aan het eind ligt er iets werkends waar je intern mee verder kunt, zonder vervolgverplichting.", "verdiepingKicker": "Verder in het traject", "verdiepingTitel": "Zes diensten voor als je al onderweg bent", "verdiepingIntro": "Niet nodig om nu te kiezen: ze komen meestal pas aan de orde als de eerste app draait of het team groeit. Voor de volledigheid staan ze hier wel.", "verdiepingRichtingTekst": "Voor als je al bouwt en wilt weten of je de goede kant op schaalt.", "verdiepingCapaciteitTekst": "Als je van één app naar een portfolio wilt en je eigen mensen het moeten dragen.", "fase1Titel": "De strategische basis", "fase1Tekst": "IT-strategie sluit nog niet aan op de bedrijfsdoelen. Er is ambitie maar geen richting.", "fase2Titel": "Van visie naar eerste resultaten", "fase2Tekst": "Er moet snel zichtbare waarde komen om draagvlak te krijgen. Het team moet gaan draaien.", "fase3Titel": "Structureren en professionaliseren", "fase3Tekst": "De eerste resultaten staan. Nu moet het beheersbaar, herhaalbaar en overdraagbaar worden.", "fase4Titel": "Schalen en innoveren", "fase4Tekst": "Meerdere teams, meerdere business units, een groeiend portfolio aan apps en agents.", "fase5Titel": "Continu evalueren", "fase5Tekst": "De vraag van de CIO: wat levert het platform op, en waar zit de volgende winst?", "ctaTitel": "Niet zeker welke dienst bij jouw vraagstuk past?"}'::jsonb || data,
       bijgewerkt_op = now()
 where slug = 'diensten';

update public.cms_paginas
   set data = '{"heroTitleStart": "Wij spreken de taal van ", "heroAccent": "jouw sector", "heroLead": "Wij kiezen bewust voor vijf sectoren in plaats van generiek IT-advies: publieke sector, mobiliteit, banken, zorg en manufacturing. In elke sector kennen we de regels, de systemen en de druk waaronder jouw organisatie werkt. Daardoor leveren we sneller iets dat écht past, in plaats van een generieke oplossing die overal een beetje werkt.", "heroKicker": "Sectoren", "keuzeKicker": "Vijf focusmarkten", "keuzeTitel": "Kies jouw sector.", "keuzeIntro": "Beweeg over een sector om het beeld te wisselen, of klik door naar de volledige sectoroplossing.", "keuzeMeer": "Jouw sector er niet bij?", "werkwijzeKicker": "Waarom sectorfocus", "werkwijzeTitel": "Wat sectorkennis je oplevert", "wijze1Titel": "Geen inwerktijd", "wijze1Tekst": "We kennen de wetgeving, ketens en kernsystemen van jouw markt. Het eerste gesprek gaat meteen over jouw vraagstuk.", "wijze2Titel": "Bewezen patronen", "wijze2Tekst": "Oplossingen die zich in jouw sector al bewezen hebben, vertalen we naar jouw organisatie, sneller live, minder risico.", "wijze3Titel": "Netwerk dat meedenkt", "wijze3Tekst": "Via onze partners en klanten in de sector leer je van organisaties die hetzelfde vraagstuk al oplosten.", "ctaTitel": "Benieuwd wat dit voor jouw organisatie betekent?"}'::jsonb || data,
