 where slug = 'sectoren';

update public.cms_paginas
   set data = '{"heroTitleStart": "Word een ", "heroAccent": "Waver", "heroLead": "Het is onze droom dat elk mens werk doet dat aansluit bij persoonlijke doelen en drijfveren. Wij verzorgen de randvoorwaarden: een gelijk speelveld, een open cultuur en alle ruimte om te groeien. Jij zorgt voor de versnelling bij onze partners.", "ctaTitel": "Eerst een kop koffie? Kom kennismaken.", "groeiKicker": "Groei & ontwikkeling", "groeiTitel": "Elke dag samen beter worden", "groeiIntro": "Persoonlijke aandacht en focus op groei zijn de kern. Samen verkennen we meerdere routes naar jouw ambitie en kiezen we de best passende weg.", "groei1Titel": "Persoonlijk groeipad", "groei1Tekst": "Jouw route bestaat uit activiteiten on-the-job, cursussen en trainingen, gekozen op basis van jouw ambitie, niet een standaardlijstje.", "groei2Titel": "Open feedbackcultuur", "groei2Tekst": "Regelmatige, open en eerlijke feedback hoort bij onze cultuur. Elk half jaar haal je bovendien 360°-feedback op uit je omgeving.", "groei3Titel": "Learning week", "groei3Tekst": "Jaarlijks trekken we er met z''n allen een volle week op uit om samen te ontwikkelen: vakinhoudelijk én persoonlijk.", "tpKicker": "Total People", "tpTitel": "Presteren, groeien én ontspannen", "tpIntro": "Bij ons staat het Total People-principe centraal: de balans tussen presteren, groeien en ontspannen. Jouw groei is onze groei.", "tp1Titel": "Presteren", "tp1Tekst": "Uitdagende opdrachten bij partners in de publieke sector, mobiliteit, banken, zorg en manufacturing. Een rol op maat die jij zelf kiest.", "tp2Titel": "Groeien", "tp2Tekst": "Zeggenschap over de koers: je beslist mee over strategie en investeringen van onze organisatie. Plus een persoonlijk groeipad met open feedback.", "tp3Titel": "Ontspannen", "tp3Tekst": "Werk dat aansluit bij jouw doelen en drijfveren, met ruimte voor rust. Duurzaam onderweg in een elektrische auto van de zaak.", "cultuurKicker": "Onze cultuur", "cultuurTitel": "Ondernemende mensen, gelijk speelveld.", "cultuurP": "Je werkt hier niet vóór ons, je werkt mét ons. Gepassioneerde consultants en engineers die naast klantteams staan en zelf ruimte krijgen om te groeien naar expertrollen.", "cultuur1": "Persoonlijk groeipad, geen vaste carrièreladder", "cultuur2": "Wavetime en Company week als vaste cultuurrituelen", "cultuur3": "Werken met bewezen frameworks (App Factory, OGSM, App in a Day) in plaats van losse projecten", "cultuur4": "Gelijke, transparante beloning bij gelijke ervaring, ongeacht gender of achtergrond", "geenMatchVoor": "Staat jouw rol er niet tussen?", "geenVacatures": "Op dit moment staan er geen vacatures open. We spreken sowieso graag met Mendix- en AI-consultants die bij ons passen.", "openSollLink": "Stuur hieronder een open sollicitatie", "belRegel": "of bel {naam}: {telefoon}.", "heroKicker": "Werken bij The New Wave IT", "heroKnopTwee": "Leer ons eerst kennen", "vacaturesKicker": "Vacatures", "vacaturesTitel": "Kom de golf versterken.", "ctaKnop": "Kom kennismaken", "openSollKop": "Open sollicitatie", "openSollIntro": "Geen passende vacature? Laat je gegevens achter, we kijken graag of er een match is.", "openSollNoot": "Na je sollicitatie neemt {naam} binnen twee werkdagen contact op. Een echt mens, geen automatische afwijzing.", "cultuurFotoAlt": "Wavers tijdens een kennissessie"}'::jsonb || data,
       bijgewerkt_op = now()
 where slug = 'werken-bij';

update public.cms_paginas
   set data = '{"kaartLink": "Lees het volledige verhaal →", "metaTitle": "Klantverhalen: resultaat dat je kunt navragen", "metaDescription": "Verhalen van organisaties in de publieke sector, mobiliteit, banken, zorg en manufacturing, verteld met de cijfers erbij.", "heroKicker": "Klantverhalen", "heroTitleStart": "Resultaat dat je kunt ", "heroAccent": "navragen", "heroTitleEnd": ".", "heroLead": "Business-impact, geen technische anekdote. Hier laten we zien wat er daadwerkelijk verandert bij een klant als strategie, Mendix en AI samenkomen: minder handwerk, snellere processen, meetbaar resultaat.", "uitgelichtKicker": "Uitgelicht", "beloftesKicker": "Onze sectoren", "beloftesTitel": "Nog geen klantverhaal in jouw sector? Dit is wat je kunt verwachten.", "beloftesIntro": "We werken pas kort genoeg samen met organisaties als Moove om al hun verhaal te kunnen delen. De rest volgt. Hieronder alvast het type resultaat dat we per sector al aantoonbaar leveren.", "ctaTitel": "Herken je jouw vraagstuk in deze verhalen?"}'::jsonb || data,
       bijgewerkt_op = now()
 where slug = 'klantverhalen';


-- Controle: twaalf regels, kolom `ontbreekt` overal 0.
with verwacht (slug, aantal) as (values
    ('sector-detail', 22),
    ('dienst-detail', 49),
    ('klantverhaal-detail', 18),
    ('vacature-detail', 36),
    ('algemeen', 15),
    ('home', 28),
    ('over-ons', 33),
    ('contact', 62),
    ('diensten', 51),
    ('sectoren', 17),
    ('werken-bij', 42),
    ('klantverhalen', 13)
)
select v.slug,
       p.status,
       (select count(*) from jsonb_object_keys(p.data)) as sleutels_in_de_rij,
       v.aantal as verwacht,
       greatest(v.aantal - (select count(*) from jsonb_object_keys(p.data)), 0) as ontbreekt
  from verwacht v
  left join public.cms_paginas p on p.slug = v.slug
 order by v.slug;
